   455  Elf32_Phdr const *
   456  PackLinuxElf32::elf_find_Phdr_for_va(upx_uint32_t addr, Elf32_Phdr const *phdr, unsigned phnum)
   457  {
   458      for (unsigned j = 0; j < phnum; ++j, ++phdr) {
   459          u32_t align = get_te32(&phdr->p_align);
   460          if (is_LOAD(phdr)
   461          && is_pow2(align) && !((-1+ align) &
   462              (get_te32(&phdr->p_vaddr) ^ get_te32(&phdr->p_offset)))
   463          &&  (addr - get_te32(&phdr->p_vaddr)) < get_te32(&phdr->p_filesz)) {
   464              return phdr;
   465          }
   466      }
   467      return nullptr;
   468  }
